import pandas as pd, os
BASE=os.path.dirname(os.path.dirname(os.path.abspath(__file__))); OUT=os.path.join(BASE,"03_processed_data"); os.makedirs(OUT,exist_ok=True)
df=pd.read_csv(os.path.join(BASE,"01_data/retail_sales_raw.csv"),parse_dates=["Order_Date"]); df["Month"]=df.Order_Date.dt.to_period("M").astype(str)
for name, g in {"monthly_sales":df.groupby("Month").agg(Sales=("Sales","sum"),Profit=("Profit","sum"),Orders=("Order_ID","count"),Quantity=("Quantity","sum")).reset_index(),"category_sales":df.groupby("Category").agg(Sales=("Sales","sum"),Profit=("Profit","sum"),Orders=("Order_ID","count")).reset_index().sort_values("Sales",ascending=False),"region_sales":df.groupby("Region").agg(Sales=("Sales","sum"),Profit=("Profit","sum"),Orders=("Order_ID","count")).reset_index().sort_values("Sales",ascending=False),"customer_segments":df.groupby("Customer_Segment").agg(Sales=("Sales","sum"),Profit=("Profit","sum"),Orders=("Order_ID","count")).reset_index(),"payment_method":df.groupby("Payment_Method").agg(Sales=("Sales","sum"),Orders=("Order_ID","count")).reset_index(),"top_10_products":df.groupby("Product").agg(Sales=("Sales","sum"),Profit=("Profit","sum"),Orders=("Order_ID","count")).reset_index().sort_values("Sales",ascending=False).head(10)}.items(): g.to_csv(os.path.join(OUT,name+".csv"),index=False)
pd.pivot_table(df,index="Category",columns="Region",values="Sales",aggfunc="sum",fill_value=0).to_csv(os.path.join(OUT,"category_region_heatmap.csv"))
pd.DataFrame([{k:v for k,v in {"Total Sales":df.Sales.sum(),"Total Profit":df.Profit.sum(),"Total Orders":len(df),"Total Quantity":df.Quantity.sum(),"Average Order Value":df.Sales.mean(),"Average Satisfaction":df.Customer_Satisfaction.mean()}.items()}]).to_csv(os.path.join(OUT,"dashboard_kpis.csv"),index=False)
print("Done")
